// SearchProducts runs a free-text search.
//
// The minimum query length is checked here rather than passed down, so an
// over-short term is rejected without a round trip to a trigram index that cannot
// help. The reasoning is the one the search service documents: below three
// characters no index can accelerate the pattern, so the query becomes a
// sequential scan of the whole index on every request, and the caller is better
// served by browsing.
func (r *queryResolver) SearchProducts(ctx context.Context, filter model1.SearchFilter) (*model.SearchResult, error) {
	ctx, span := r.traceRoot(ctx, "Query", "searchProducts")
	defer span.End()

	query := strings.TrimSpace(filter.Query)
	if query == "" {
		return nil, &apperror.InvalidInput{Message: "a search query is required; use products to browse the catalogue"}
	}
	if len(query) < minSearchTermLength {
		return nil, &apperror.InvalidInput{Message: "search terms must be at least 3 characters; use products to browse the catalogue"}
	}

	status := model.StatusUnknown
	if filter.Status != nil {
		parsed, err := model.ParseStatus(string(*filter.Status))
		if err != nil {
			return nil, &apperror.InvalidInput{Message: err.Error()}
		}
		status = parsed
	}

	categoryID := ""
	if filter.CategoryID != nil {
		categoryID = *filter.CategoryID
	}

	result, err := r.SearchStore.SearchProducts(ctx, SearchFilter{
		Query:         query,
		CategoryID:    categoryID,
		Status:        status,
		MinPriceCents: int64Value(filter.MinPriceCents),
		MaxPriceCents: int64Value(filter.MaxPriceCents),
		Limit:         limitWithBounds(filter.Limit),
		Offset:        offsetOrZero(filter.Offset),
	})
	if err != nil {
		return nil, err
	}
	return &model.SearchResult{
		Hits:   result.Hits,
		Total:  result.Total,
		Limit:  result.Limit,
		Offset: result.Offset,
		TookMS: result.TookMS,
	}, nil
}

