// Category is the batch resolver for the category field.
func (r *searchHitResolver) Category(ctx context.Context, objs []*model.SearchHit) ([]*model.Category, error) {
	// One span for the whole batch. The downstream call this resolver makes is a single
	// call for every parent, so a span per parent would describe a fan-out that does not
	// happen. The dependents count is what makes the batching visible in a trace.
	ctx, span := r.traceField(ctx, "SearchHit", "category", len(objs))
	defer span.End()
	r.Observer().ReportDependents(span, len(objs))

	out := make([]*model.Category, len(objs))
	if len(objs) == 0 {
		return out, nil
	}

	ids := uniqueHitCategoryIDs(objs)
	if len(ids) == 0 {
		return out, nil
	}

	byID, err := r.CategoryStore.CategoriesByIDs(ctx, ids)
	if err != nil {
		recordError(ctx, err, "SearchHit.category", "category-service")
		return out, nil
	}
	for i, h := range objs {
		if h == nil || h.CategoryID == "" {
			continue
		}
		if cat, ok := byID[h.CategoryID]; ok {
			out[i] = &cat
		}
	}
	return out, nil
}

// PrimaryMedia is the batch resolver for the primaryMedia field.
func (r *searchHitResolver) PrimaryMedia(ctx context.Context, objs []*model.SearchHit) ([]*model.Media, error) {
	// One span for the whole batch. The downstream call this resolver makes is a single
	// call for every parent, so a span per parent would describe a fan-out that does not
	// happen. The dependents count is what makes the batching visible in a trace.
	ctx, span := r.traceField(ctx, "SearchHit", "primaryMedia", len(objs))
	defer span.End()
	r.Observer().ReportDependents(span, len(objs))

	out := make([]*model.Media, len(objs))
	if len(objs) == 0 {
		return out, nil
	}

	ids := uniqueMediaIDs(mediaIDsOfHits(objs))
	if len(ids) == 0 {
		return out, nil
	}

	byID, err := r.MediaStore.MediaByIDs(ctx, ids)
	if err != nil {
		recordError(ctx, err, "SearchHit.primaryMedia", "media-service")
		return out, nil
	}
	for i, h := range objs {
		if h == nil || h.PrimaryMediaID == "" {
			continue
		}
		if m, ok := byID[h.PrimaryMediaID]; ok {
			out[i] = &m
		}
	}

	// Signed here rather than by a field resolver on Media, so the whole page costs one
	// presign call. See signURLs for why the resolver form cannot be batched here.
	r.signURLs(ctx, "SearchHit.primaryMedia", out)
	return out, nil
}

